from html.parser import HTMLParser
from pathlib import Path
import sys
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_a=False; self.href=''; self.title=''; self.text=[]; self.tab=None; self.out=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='div' and d.get('class') and 'tab-pane' in d.get('class',''):
            self.tab=d.get('id')
        if tag=='a' and self.tab in {'nav-ug','nav-pg','nav-allc'}:
            self.in_a=True; self.href=d.get('href',''); self.title=d.get('title',''); self.text=[]
    def handle_data(self,data):
        if self.in_a: self.text.append(' '.join(data.split()))
    def handle_endtag(self,tag):
        if tag=='a' and self.in_a:
            t=' '.join(' '.join(self.text).split())
            if self.href.startswith('http') and '/programmes/' in self.href:
                self.out.append((self.tab,self.href,self.title,t))
            self.in_a=False
p=P(); p.feed(Path(sys.argv[1]).read_text(errors='ignore'))
for x in p.out: print('\\t'.join(x))
PY"

